/**
 * An authenticated acknowledgment.
 *
 * Commit its changes before clearing the app's own delivery state.
 */
public struct AcknowledgmentResult: Equatable, Hashable {
    /**
     * The session the acknowledgment arrived on.
     */
    public var sessionId: SessionId
    /**
     * The acknowledgment's own message ID.
     */
    public var messageId: MessageId
    /**
     * Authenticated sender timestamp in milliseconds.
     */
    public var sentAtMillis: UInt64
    /**
     * The outbound message ID the acknowledgment names.
     */
    public var acknowledgedMessageId: MessageId
    /**
     * Authenticated sender material.
     */
    public var senderIdentity: SenderIdentityMaterial

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(
        /**
         * The session the acknowledgment arrived on.
         */sessionId: SessionId, 
        /**
         * The acknowledgment's own message ID.
         */messageId: MessageId, 
        /**
         * Authenticated sender timestamp in milliseconds.
         */sentAtMillis: UInt64, 
        /**
         * The outbound message ID the acknowledgment names.
         */acknowledgedMessageId: MessageId, 
        /**
         * Authenticated sender material.
         */senderIdentity: SenderIdentityMaterial) {
        self.sessionId = sessionId
        self.messageId = messageId
        self.sentAtMillis = sentAtMillis
        self.acknowledgedMessageId = acknowledgedMessageId
        self.senderIdentity = senderIdentity
    }

    

    
}

