    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ProtocolStateKind {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .ratchetSession
        
        case 2: return .deduplicationSet
        
        case 3: return .pendingAcknowledgments
        
        case 4: return .contactState
        
        case 5: return .peerSessions
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ProtocolStateKind, into buf: inout [UInt8]) {
        switch value {
        
        
        case .ratchetSession:
