        case .deduplicationSet:
            writeInt(&buf, Int32(2))
        
        
        case .pendingAcknowledgments:
            writeInt(&buf, Int32(3))
        
        
        case .contactState:
            writeInt(&buf, Int32(4))
        
        
        case .peerSessions:
            writeInt(&buf, Int32(5))
        
        }
    }
}


