public struct FfiConverterTypeRoostError: FfiConverterRustBuffer {
    typealias SwiftType = RoostError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> RoostError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .AlreadyExists
        case 2: return .AuthenticationFailed(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 3: return .BackupFailed(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 4: return .BlockedContact(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 5: return .CertificateRejected(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 6: return .ContactNotAccepted(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 7: return .Corrupt
        case 8: return .DecryptionFailed
        case 9: return .InternalError(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 10: return .InvalidData(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 11: return .InboxRotationRequired
        case 12: return .NoDeliveryCapability
        case 13: return .NotFound
        case 14: return .OneTimePreKeyUsed(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 15: return .OperationFinished
        case 16: return .OperationConflict(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 17: return .UnfinishedReservation(
            operationId: try FfiConverterTypeOperationId.read(from: &buf), 
            reason: try FfiConverterString.read(from: &buf)
            )
        case 18: return .ProtocolStateFault(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 19: return .Storage(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 20: return .SecureStoragePreconditionChanged(
            key: try FfiConverterString.read(from: &buf)
            )
        case 21: return .TooManyUnfinishedOperations
        case 22: return .TooManyPendingAcknowledgments(
            limit: try FfiConverterUInt64.read(from: &buf)
            )
        case 23: return .UnsupportedVersion(
            reason: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: RoostError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case .AlreadyExists:
            writeInt(&buf, Int32(1))
        
        
        case let .AuthenticationFailed(reason):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .BackupFailed(reason):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .BlockedContact(reason):
            writeInt(&buf, Int32(4))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .CertificateRejected(reason):
            writeInt(&buf, Int32(5))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .ContactNotAccepted(reason):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(reason, into: &buf)
            
        
        case .Corrupt:
            writeInt(&buf, Int32(7))
        
        
        case .DecryptionFailed:
            writeInt(&buf, Int32(8))
        
        
        case let .InternalError(reason):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .InvalidData(reason):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(reason, into: &buf)
            
        
        case .InboxRotationRequired:
            writeInt(&buf, Int32(11))
        
        
        case .NoDeliveryCapability:
            writeInt(&buf, Int32(12))
        
        
        case .NotFound:
            writeInt(&buf, Int32(13))
        
        
        case let .OneTimePreKeyUsed(reason):
            writeInt(&buf, Int32(14))
            FfiConverterString.write(reason, into: &buf)
            
        
        case .OperationFinished:
            writeInt(&buf, Int32(15))
        
        
        case let .OperationConflict(reason):
            writeInt(&buf, Int32(16))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .UnfinishedReservation(operationId,reason):
            writeInt(&buf, Int32(17))
            FfiConverterTypeOperationId.write(operationId, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .ProtocolStateFault(reason):
            writeInt(&buf, Int32(18))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Storage(reason):
            writeInt(&buf, Int32(19))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .SecureStoragePreconditionChanged(key):
            writeInt(&buf, Int32(20))
            FfiConverterString.write(key, into: &buf)
            
        
        case .TooManyUnfinishedOperations:
            writeInt(&buf, Int32(21))
        
        
        case let .TooManyPendingAcknowledgments(limit):
            writeInt(&buf, Int32(22))
            FfiConverterUInt64.write(limit, into: &buf)
            
        
        case let .UnsupportedVersion(reason):
            writeInt(&buf, Int32(23))
            FfiConverterString.write(reason, into: &buf)
            
        }
    }
}


